// vert_bench.cpp - micro-benchmark of the vertical kernels (vert.h) against the production scalar functions.
// build: g++ -std=c++20 -O3 -march=x86-64 -pthread -static -o vert_bench vert_bench.cpp
// run:   vert_bench [threads=8] [seconds_per_case=0.3] [prefix]   (prefix: only the cases whose name starts with it, e.g. cl; the v1/v2 cases run only when asked for this way)
// Output: one line per case:  case ns_per_row [kernel_ns_per_row chunk_ns_per_row]
// vert_bench4: the line-form kernel in its versions and stages (see the comments at the kernels below).
// Cases: id_* = K1 (event ID -> counter); ev_* = K1 + both timestamps + date + kind + validity (the whole content
// part of an event row); evz_v5 = ev_v5 + vplzcntq + one more 512-bit gather + vpmullq (what a line-level kernel adds).
//   "X"        kernel only (operands already in arrays; scalar = production functions on the row text)
//   "X+chunk"  per batch of 8 rows: the kernel, then 8 x a fixed chunk of ordinary scalar integer work
//              (~300 instructions); the two parts are timed separately with rdtsc, so a frequency drop caused
//              by the vector code shows up as a slower chunk than in the "chunk" case (chunk alone).
// All threads run the same case at the same time.
// prod.h - VERBATIM copies of production functions from /home/claude/wtA/main.cpp (snapshot, generated by sed line ranges; do not edit)
#include <immintrin.h>
