 const __m128i d=_mm_min_epu8(t,_mm_add_epi8(v,_mm_load_si128(K+4)));
 const __m128i p4=_mm_madd_epi16(_mm_maddubs_epi16(d,_mm_load_si128(K+5)),_mm_load_si128(K+6));
