 _mm512_store_si512((void*)o.uct,_mm512_mask_or_epi64(tid,valid,tid,_mm512_or_si512(un,VERT_K5(70))));
 _mm512_store_si512((void*)o.uw,_mm512_maskz_mov_epi64(valid,uw));
