 _mm512_store_si512((void*)o.s6,S6);_mm512_store_si512((void*)o.l6,l6);
 ok=_kand_mask8(ok,idok);
 o.idok=(uint8_t)idok;o.ok=(uint8_t)ok;o.pur=(uint8_t)_kand_mask8(pur,ok);
